export function realmSlot(key) {
    const symbol = typeof key === 'symbol' ? key : Symbol.for(key);
    return {
        set(host, value) {
            Object.defineProperty(host, symbol, {
                value,
                enumerable: false,
                configurable: true,
                writable: false,
            });
        },
        get(host) {
            if ((typeof host !== 'object' || host === null) && typeof host !== 'function') {
                return undefined;
            }
            return host[symbol];
        },
        delete(host) {
            delete host[symbol];
        },
    };
}
